/* Uiverse · MuhammadHasann/lucky-mouse-99 */
background: #FEC195;
border-radius: 8px;
border: 1px solid #FEC195;
color: #181818;
box-shadow: 2px 2px 3px rgba(0,0,0,.2);

search.css:
.demo-page {
  min-height: 100vh;
  display: grid;
  place-items: center;
  padding: 24px;

  background:
    radial-gradient(circle at 20% 20%, #526cff, transparent 32%),
    radial-gradient(circle at 80% 70%, #d35cff, transparent 30%),
    linear-gradient(135deg, #101322, #252849);

  font-family:
    -apple-system,
    BlinkMacSystemFont,
    "SF Pro Display",
    "PingFang SC",
    "Microsoft YaHei",
    sans-serif;
}

.profile-card {
  width: min(360px, 100%);
  text-align: center;
}

.profile-card h2 {
  margin: 16px 0 8px;
  font-size: 28px;
  letter-spacing: -0.03em;
}

.profile-card p {
  margin: 0 0 24px;
  color: rgba(255, 255, 255, 0.7);
}

.avatar {
  width: 72px;
  height: 72px;
  display: grid;
  place-items: center;
  margin: 0 auto;

  border-radius: 50%;
  font-size: 28px;
  font-weight: 700;

  background: linear-gradient(135deg, #8ec5ff, #e7a7ff);
  box-shadow:
    inset 0 1px 2px rgba(255, 255, 255, 0.8),
    0 10px 30px rgba(128, 157, 255, 0.35);
}

.glass-button {
  border: 1px solid rgba(255, 255, 255, 0.35);
  border-radius: 999px;
  padding: 12px 22px;

  color: white;
  background: rgba(255, 255, 255, 0.16);
  backdrop-filter: blur(12px);
  -webkit-backdrop-filter: blur(12px);

  font-size: 15px;
  cursor: pointer;
  transition: 0.25s ease;
}

.glass-button:hover {
  background: rgba(255, 255, 255, 0.28);
  transform: scale(1.04);
}

.glass-button:active {
  transform: scale(0.96);
}

